<?php require "page-guard.php"; require "../config/db_conn.php"; require "../includes/attendance-schema.php"; ensureAttendanceTimeOutColumn($conn); require "components.php";
$totalStudents=$conn->query("SELECT COUNT(*) total FROM students")->fetch_assoc()['total'];$today=date('Y-m-d');$q=$conn->prepare("SELECT COUNT(DISTINCT STUDENT_ID) total FROM attendance WHERE DATE(TIME_IN)=?");$q->bind_param('s',$today);$q->execute();$todayCount=$q->get_result()->fetch_assoc()['total'];$q=$conn->prepare("SELECT COUNT(DISTINCT STUDENT_ID) total FROM attendance WHERE DATE(TIME_IN)=? AND TIME_OUT IS NOT NULL");$q->bind_param('s',$today);$q->execute();$timeOutCount=$q->get_result()->fetch_assoc()['total'];adminHead('Dashboard');adminSidebar('dashboard','Dashboard','Your attendance overview for today'); ?>
<div class="mb-7"><h2 class="text-2xl font-black text-slate-900">Good day, administrator.</h2><p class="mt-1 text-slate-500">Here is what is happening across the system.</p></div>
<section class="grid gap-5 md:grid-cols-3"><article class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><p class="text-sm font-bold text-slate-500">Registered students</p><p id="stat-total" class="mt-3 text-4xl font-black text-slate-900"><?= $totalStudents ?></p><p class="mt-2 text-sm text-slate-500">Student profiles in the system</p></article><article class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><p class="text-sm font-bold text-emerald-700">Today's time ins</p><p id="stat-today" class="mt-3 text-4xl font-black text-slate-900"><?= $todayCount ?></p><p class="mt-2 text-sm text-slate-500">Unique students who arrived today</p></article><article class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><p class="text-sm font-bold text-amber-700">Today's time outs</p><p id="stat-time-out" class="mt-3 text-4xl font-black text-slate-900"><?= $timeOutCount ?></p><p class="mt-2 text-sm text-slate-500">Unique students dismissed today</p></article></section>
<section class="mt-7 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 class="text-xl font-bold text-slate-900">Camera attendance</h2><p class="mt-2 text-slate-500">Select the camera to use, then open the full-screen attendance scanner.</p><form action="scan-attendance.php" method="get" class="mt-5 flex flex-wrap items-center gap-3"><label class="min-w-64 flex-1 text-sm font-bold text-slate-700"><span class="mb-2 block">Camera</span><select id="dashboard-camera" name="camera" class="w-full rounded-xl border border-slate-300 bg-white px-4 py-3 text-slate-800" disabled><option>Loading available cameras…</option></select></label><button class="mt-6 inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-3 font-bold text-white hover:bg-blue-700"><span aria-hidden="true">&#9673;</span> Open attendance scanner</button></form><p id="camera-help" class="mt-3 text-sm text-slate-500">Allow camera access to choose a device.</p></section>
<script>const cameraSelect=document.getElementById('dashboard-camera'),cameraHelp=document.getElementById('camera-help');async function loadCameras(){try{const preview=await navigator.mediaDevices.getUserMedia({video:true,audio:false});preview.getTracks().forEach(t=>t.stop());const devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');const saved=localStorage.getItem('attendance-camera');cameraSelect.innerHTML=devices.map((d,i)=>`<option value="${d.deviceId}">${d.label||`Camera ${i+1}`}</option>`).join('');if(saved&&[...cameraSelect.options].some(o=>o.value===saved))cameraSelect.value=saved;cameraSelect.disabled=false;cameraHelp.textContent=devices.length?'Camera ready. Your selection is remembered on this device.':'No camera was found.'}catch(e){cameraSelect.innerHTML='<option value="">Default camera</option>';cameraSelect.disabled=false;cameraHelp.textContent='Camera permission was not granted. The scanner will ask again.'}}cameraSelect.addEventListener('change',()=>localStorage.setItem('attendance-camera',cameraSelect.value));loadCameras();setInterval(()=>fetch('get-stats.php').then(r=>r.json()).then(d=>{document.getElementById('stat-total').textContent=d.totalStudents;document.getElementById('stat-today').textContent=d.attendanceToday;document.getElementById('stat-time-out').textContent=d.timeOutToday}).catch(()=>{}),5000)</script><?php adminFoot(); ?>
